from pathlib import Path
import subprocess,base64,hashlib
DATA=''
SHA='f83c0c821e52b232b894ad12dbe52cadcf7d4765dc95456cd9500f1448ed3739'

root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review')
p=root/'tools/stage5_03_probe_run.py';assert not p.exists() and not root.is_symlink()
data=base64.b64decode(DATA);assert hashlib.sha256(data).hexdigest()==SHA;p.write_bytes(data)
for name,fixed,samples in [('baseline_live_12',False,12),('baseline_fixed_6',True,6)]:
 command=['python3',str(p),'--name',name,'--variant','baseline','--samples',str(samples)]
 if fixed:command+=['--fixed']
 result=subprocess.run(command,timeout=240)
 if result.returncode:raise SystemExit(result.returncode)
